<div class="d-flex gap-2 align-items-center mb-3"><h2 class="h5 mb-0"><?= e($a['title']) ?> — <?= e($a['full_name']) ?></h2><span class="badge text-bg-info">الدرجة: <?= $a['score'] === null ? '—' : (float)$a['score'] ?></span><a class="btn btn-outline-secondary ms-auto" href="<?= url('school/lms/quizzes/' . (int)$a['quiz_id']) ?>">رجوع</a></div>
<?php foreach ($a['rows'] as $i => $q): $given = $q['given']; ?><div class="card-s mb-2"><div class="d-flex gap-2"><strong><?= $i + 1 ?>.</strong><div class="flex-grow-1"><span class="math-content"><?= e($q['body']) ?></span> <span class="badge text-bg-secondary"><?= (float)$q['pts'] ?></span><?= !empty($q['image_file_id']) ? '<div class="mt-2">' . qimg((int)$q['image_file_id']) . '</div>' : '' ?></div></div>
  <div class="small mt-1">إجابة الطالب: <strong><?php if ($given === null || $given === ''): ?><span class="text-muted">لم يجب</span><?php elseif ($q['kind'] === 'mcq'): ?><?= qopt($q, $given) ?: '—' ?><?php elseif ($q['kind'] === 'true_false'): ?><?= $given ? 'صح' : 'خطأ' ?><?php else: ?><span style="white-space:pre-wrap"><?= e($given) ?></span><?php endif; ?></strong></div>
  <?php if ($q['kind'] === 'mcq'): ?><div class="small text-success">الصحيح: <?= qopt($q, $q['answer']) ?></div><?php elseif ($q['kind'] === 'true_false'): ?><div class="small text-success">الصحيح: <?= $q['answer'] ? 'صح' : 'خطأ' ?></div><?php elseif ($q['kind'] === 'short'): ?><div class="small text-success">المقبول: <?= e(implode(' / ', $q['answer'] ?: [])) ?></div><?php endif; ?>
  <?php if ($a['status'] !== 'in_progress'): ?><form class="d-flex gap-2 align-items-center mt-2" method="post" action="<?= url('api/v1/school/lms/attempts/' . (int)$a['id'] . '/grade') ?>" data-ajax data-reload novalidate><?= csrf_field() ?><input type="hidden" name="question_id" value="<?= (int)$q['id'] ?>"><input class="form-control" style="max-width:110px" name="score" type="number" step="0.01" min="0" max="<?= (float)$q['pts'] ?>" value="<?= $q['score'] === null ? '' : (float)$q['score'] ?>" placeholder="الدرجة" aria-label="الدرجة"><button class="btn btn-sm btn-primary" type="submit">حفظ</button><?php if ($q['score'] === null): ?><span class="badge text-bg-warning">بانتظار التصحيح</span><?php endif; ?></form><?php endif; ?></div><?php endforeach; ?>
